import React, { useState, useEffect } from "react";
import "./Dashboard.css";

const Dashboard = () => {
  const [websites, setWebsites] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState("all");
  const [searchTerm, setSearchTerm] = useState("");

  // Mock data - replace with actual API calls
  useEffect(() => {
    // Simulate API fetch
    const fetchWebsites = async () => {
      try {
        // Replace with your actual API call
        const mockData = [
          {
            id: 1,
            name: "Bella's Cafe",
            url: "https://bellascafe.com",
            status: "online",
            lastUpdated: "2023-05-15",
            uptime: "99.9%",
            issues: 0,
            clientSince: "2022-01-10",
          },
          {
            id: 2,
            name: "Urban Fitness",
            url: "https://urbanfitnessgym.com",
            status: "offline",
            lastUpdated: "2023-05-14",
            uptime: "98.2%",
            issues: 2,
            clientSince: "2021-11-22",
          },
          {
            id: 3,
            name: "Green Thumb Landscaping",
            url: "https://greenthumb-landscaping.com",
            status: "online",
            lastUpdated: "2023-05-16",
            uptime: "99.5%",
            issues: 1,
            clientSince: "2023-02-05",
          },
        ];

        setWebsites(mockData);
        setLoading(false);
      } catch (error) {
        console.error("Error fetching websites:", error);
        setLoading(false);
      }
    };

    fetchWebsites();
  }, []);

  const filteredWebsites = websites.filter((website) => {
    const matchesSearch =
      website.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      website.url.toLowerCase().includes(searchTerm.toLowerCase());

    if (activeTab === "all") return matchesSearch;
    if (activeTab === "online")
      return website.status === "online" && matchesSearch;
    if (activeTab === "offline")
      return website.status === "offline" && matchesSearch;
    if (activeTab === "issues") return website.issues > 0 && matchesSearch;

    return matchesSearch;
  });

  const handleStatusUpdate = (id, newStatus) => {
    setWebsites(
      websites.map((website) =>
        website.id === id ? { ...website, status: newStatus } : website
      )
    );
  };

  const getStatusColor = (status) => {
    switch (status) {
      case "online":
        return "status-online";
      case "offline":
        return "status-offline";
      case "maintenance":
        return "status-maintenance";
      default:
        return "";
    }
  };

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <h1>Client Websites Dashboard</h1>
        <p>Monitor all the websites you've developed for your clients</p>
      </header>

      <div className="dashboard-controls">
        <div className="search-bar">
          <input
            type="text"
            placeholder="Search websites..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <button className="search-button">
            <i className="fas fa-search"></i>
          </button>
        </div>

        <div className="filter-tabs">
          <button
            className={activeTab === "all" ? "active" : ""}
            onClick={() => setActiveTab("all")}
          >
            All Sites ({websites.length})
          </button>
          <button
            className={activeTab === "online" ? "active" : ""}
            onClick={() => setActiveTab("online")}
          >
            Online ({websites.filter((w) => w.status === "online").length})
          </button>
          <button
            className={activeTab === "offline" ? "active" : ""}
            onClick={() => setActiveTab("offline")}
          >
            Offline ({websites.filter((w) => w.status === "offline").length})
          </button>
          <button
            className={activeTab === "issues" ? "active" : ""}
            onClick={() => setActiveTab("issues")}
          >
            With Issues ({websites.filter((w) => w.issues > 0).length})
          </button>
        </div>
      </div>

      {loading ? (
        <div className="loading-spinner">
          <div className="spinner"></div>
          <p>Loading client websites...</p>
        </div>
      ) : (
        <div className="websites-grid">
          {filteredWebsites.length > 0 ? (
            filteredWebsites.map((website) => (
              <div key={website.id} className="website-card">
                <div className="card-header">
                  <h3>{website.name}</h3>
                  <span
                    className={`status-badge ${getStatusColor(website.status)}`}
                  >
                    {website.status}
                  </span>
                </div>

                <div className="card-body">
                  <div className="website-info">
                    <p>
                      <strong>URL:</strong>{" "}
                      <a
                        href={website.url}
                        target="_blank"
                        rel="noopener noreferrer"
                      >
                        {website.url}
                      </a>
                    </p>
                    <p>
                      <strong>Last Updated:</strong> {website.lastUpdated}
                    </p>
                    <p>
                      <strong>Uptime:</strong> {website.uptime}
                    </p>
                    <p>
                      <strong>Issues:</strong> {website.issues}
                    </p>
                    <p>
                      <strong>Client Since:</strong> {website.clientSince}
                    </p>
                  </div>

                  <div className="card-actions">
                    <button
                      className="btn view-btn"
                      onClick={() => window.open(website.url, "_blank")}
                    >
                      Visit Site
                    </button>
                    <button className="btn analytics-btn">
                      View Analytics
                    </button>
                    <select
                      value={website.status}
                      onChange={(e) =>
                        handleStatusUpdate(website.id, e.target.value)
                      }
                      className={`status-select ${getStatusColor(
                        website.status
                      )}`}
                    >
                      <option value="online">Online</option>
                      <option value="offline">Offline</option>
                      <option value="maintenance">Maintenance</option>
                    </select>
                  </div>
                </div>
              </div>
            ))
          ) : (
            <div className="no-results">
              <p>No websites found matching your criteria.</p>
            </div>
          )}
        </div>
      )}

      <div className="dashboard-summary">
        <div className="summary-card">
          <h4>Total Websites</h4>
          <p className="summary-value">{websites.length}</p>
        </div>
        <div className="summary-card">
          <h4>Online Now</h4>
          <p className="summary-value">
            {websites.filter((w) => w.status === "online").length}
          </p>
        </div>
        <div className="summary-card">
          <h4>With Issues</h4>
          <p className="summary-value">
            {websites.filter((w) => w.issues > 0).length}
          </p>
        </div>
        <div className="summary-card">
          <h4>Average Uptime</h4>
          <p className="summary-value">
            {websites.length > 0
              ? (
                  websites.reduce(
                    (sum, site) => sum + parseFloat(site.uptime),
                    0
                  ) / websites.length
                ).toFixed(1) + "%"
              : "N/A"}
          </p>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
